CREATE TABLE trips(id VARCHAR2(36) PRIMARY KEY,owner_id VARCHAR2(36) NOT NULL,title VARCHAR2(200) NOT NULL,destination VARCHAR2(200) NOT NULL,timezone VARCHAR2(80) NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL,CHECK(end_date>=start_date));
CREATE INDEX trips_owner ON trips(owner_id);
CREATE TABLE trip_members(trip_id VARCHAR2(36) REFERENCES trips(id),account_id VARCHAR2(36),role VARCHAR2(10) NOT NULL CHECK(role IN ('EDITOR','VIEWER')),accepted NUMBER(1) DEFAULT 0 NOT NULL,PRIMARY KEY(trip_id,account_id));
CREATE TABLE itinerary_versions(id VARCHAR2(36) PRIMARY KEY,trip_id VARCHAR2(36) NOT NULL REFERENCES trips(id),status VARCHAR2(20) NOT NULL CHECK(status IN ('DRAFT','APPROVED','SUPERSEDED')),source VARCHAR2(500) NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL);
CREATE INDEX itinerary_trip ON itinerary_versions(trip_id,status);
CREATE TABLE activities(id VARCHAR2(36) PRIMARY KEY,itinerary_id VARCHAR2(36) NOT NULL REFERENCES itinerary_versions(id),sequence_no NUMBER(5) NOT NULL,title VARCHAR2(200) NOT NULL,starts_at TIMESTAMP WITH TIME ZONE NOT NULL,ends_at TIMESTAMP WITH TIME ZONE NOT NULL,latitude NUMBER(10,7) NOT NULL CHECK(latitude BETWEEN -90 AND 90),longitude NUMBER(10,7) NOT NULL CHECK(longitude BETWEEN -180 AND 180),source VARCHAR2(500) NOT NULL,CHECK(ends_at>starts_at),UNIQUE(itinerary_id,sequence_no));
CREATE TABLE activity_votes(activity_id VARCHAR2(36) REFERENCES activities(id),account_id VARCHAR2(36),vote_value NUMBER(1) NOT NULL CHECK(vote_value BETWEEN -1 AND 1),PRIMARY KEY(activity_id,account_id));
CREATE TABLE calendar_events(id VARCHAR2(36) PRIMARY KEY,trip_id VARCHAR2(36) NOT NULL REFERENCES trips(id),title VARCHAR2(200) NOT NULL,starts_at TIMESTAMP WITH TIME ZONE NOT NULL,ends_at TIMESTAMP WITH TIME ZONE NOT NULL,timezone VARCHAR2(80) NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL,CHECK(ends_at>starts_at));
CREATE TABLE essential_contacts(id VARCHAR2(36) PRIMARY KEY,trip_id VARCHAR2(36) NOT NULL REFERENCES trips(id),label VARCHAR2(100) NOT NULL,phone VARCHAR2(50) NOT NULL);
